    /** Balken mit Farbverlauf: Zeichen first + n - 1 = die ersten n Spalten und die Endspalte (n < width). */
    public enum Strip {
        PT_GOLD('\ue000', 198, 8),
        IB_BODY_FROST('\ue100', 128, 18),
        IB_BODY_KRISTALL('\ue200', 128, 18),
        IB_BODY_KRONE('\ue300', 128, 18),
        IB_BODY_WALD('\ue400', 128, 18),
        PF_BAR('\ue500', 128, 10),
        PF_FILL_GOLD('\ue600', 128, 10),
        PF_FILL_GREEN('\ue700', 128, 10),
        QU_BAR('\ue800', 128, 6),
        QU_FILL_CREAM('\ueb00', 128, 6),
        QU_FILL_GOLD('\uf600', 128, 6);

        public final char first;
        public final int width, height;

        Strip(char first, int width, int height) {
            this.first = first;
            this.width = width;
            this.height = height;
        }
    }

    /** Titelschrift (Schriften kuby:k/i<s> und kuby:title): Zeichen in TITLE_CHARS, Glyphe = Start + Index. */
    public static final String TITLE_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!?.,:-+/%'&#$\u2726\u2605\u00c4\u00d6\u00dc ";
